from pathlib import Path
from html import escape as e
import json
root=Path(__file__).parent
base='https://liulijing1.github.io'
papers=[dict(slug='iberian-electricity',title='Renewable electricity is associated with wholesale price resilience in sustainable Iberian power markets',authors=['Lijing Liu','Elisabeth T. Pereira','Hao Wu'],date='2026-09-24',journal='Discover Sustainability',doi='10.1007/s43621-026-04754-w',status='Published research · Open access',summary='This study examines renewable electricity, wholesale prices, gas-price pass-through and Spain–Portugal price dispersion in the Iberian day-ahead market using matched daily samples for 2019–2025.',findings=['Renewable generation is negatively associated with day-ahead prices: −0.987 EUR/MWh per percentage point in the total estimate, and −0.699 EUR/MWh conditional on gas generation.','Renewable penetration is associated with weaker within-month gas-price pass-through; the renewable–gas interaction estimate is −0.438.','Additional internal Spain–Portugal commercial capacity is associated with narrower hourly absolute price spreads: −2.924 EUR/MWh per additional GW.'],limits='These estimates are conditional associations, not causal effects. The policy-window comparisons describe temporal heterogeneity and do not establish a causal effect of the Iberian Exception.',keywords='Renewable electricity, price resilience, gas-price pass-through, MIBEL, market coupling'),dict(slug='china-solar-pv',title='Reassessing the International Competitiveness and Economic Sustainability of China’s Solar PV Industry: A Systematic Review and Evidence Synthesis',authors=['Lijing Liu','Maria Elisabeth Teixeira Pereira'],date='2026',journal='Energies',doi='10.3390/en19020508',status='Published review',summary='A systematic review and evidence synthesis on the international competitiveness and economic sustainability of China’s solar photovoltaic industry. Follow the DOI for the publisher’s abstract and full text.',findings=[],limits='',keywords='Solar PV, China, international competitiveness, economic sustainability, systematic review'),dict(slug='generative-ai-academic-authority',title='Conversion Without Redistribution: Generative AI and Academic Authority in International Publishing',authors=['Lijing Liu','Maria Elisabeth Teixeira Pereira'],date='2026-07-07',journal='Preprints.org',doi='10.20944/preprints202607.0406.v1',status='Preprint v1 · Not peer reviewed',summary='This preprint examines whether the early post-ChatGPT period is associated with changes in global academic participation, authorship leadership and recognition. It uses OpenAlex metadata and distinguishes easier conversion of existing research capacity into manuscripts from redistribution of research resources and recognition.',findings=['The work-level sample covers 51,840 works; the balanced panel covers 13,860 country–subfield–year cells.','Annual diagnostics identify a more selective pattern in disadvantaged-country first authorship, rather than broad and stable gains across participation and recognition.'],limits='The evidence does not identify a causal democratization effect of generative AI. This is a preprint and has not been peer reviewed.',keywords='Generative AI, academic inequality, international publishing, authorship, OpenAlex')]
abstracts=json.loads((root/'abstracts.json').read_text())
papers[0]['status']='Published research · Early publication · Open access'
papers[1]['date']='2026-01-20'
fulltext={'iberian-electricity':'https://link.springer.com/content/pdf/10.1007/s43621-026-04754-w_reference.pdf','china-solar-pv':'https://www.mdpi.com/1996-1073/19/2/508','generative-ai-academic-authority':'https://www.preprints.org/manuscript/202607.0406/v1'}
css='''body{margin:0;background:#f6f7f4;color:#18322d;font:18px/1.65 system-ui,sans-serif}main{max-width:900px;margin:auto;padding:52px 24px}a{color:#146b60;text-underline-offset:4px}h1{font-size:clamp(30px,5vw,48px);line-height:1.2;letter-spacing:-.025em}h2{font-size:25px;margin-top:36px}.eyebrow{font-size:14px;text-transform:uppercase;letter-spacing:.1em;color:#53746c}.card{padding:25px 0;border-top:1px solid #cbd8d1}.meta,footer{font-size:15px;color:#53746c}.links{display:flex;flex-wrap:wrap;gap:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e9efe9;padding:20px;font-size:14px}li{margin:12px 0}footer{margin-top:48px;border-top:1px solid #cbd8d1;padding-top:20px}'''
(root/'style.css').write_text(css)
def page(title,body,path,metadata='',structured=None):
 url=base+path
 return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="google-site-verification" content="chkmeLCVuFcnHYpz33h94tfVjrupTZBLaRz0lYkFe44"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+'</title><meta name="robots" content="index,follow"><link rel="canonical" href="'+url+'"><link rel="stylesheet" href="/style.css">'+metadata+('<script type="application/ld+json">'+json.dumps(structured,ensure_ascii=False).replace('</','<\\/')+'</script>' if structured else '')+'</head><body><main>'+body+'<footer>Lijing Liu · <a href="https://orcid.org/0000-0001-7200-9192">ORCID</a> · <a href="https://github.com/liulijing1/liulijing1.github.io">Site source</a><br>Research summaries link to the original scholarly records. Cite the paper DOI. Information checked 1 October 2026.</footer></main></body></html>'
cards=''
for p in papers:
 directory=root/'papers'/p['slug'];directory.mkdir(parents=True,exist_ok=True)
 path='/papers/'+p['slug']+'/'
 doi='https://doi.org/'+p['doi']
 bib='@'+('misc' if 'Preprint' in p['status'] else 'article')+'{liu2026'+p['slug'].replace('-','')+',\n  title = {'+p['title']+'},\n  author = {'+' and '.join(p['authors'])+'},\n  year = {2026},\n  '+('howpublished' if 'Preprint' in p['status'] else 'journal')+' = {'+p['journal']+'},\n  doi = {'+p['doi']+'},\n  url = {'+doi+'}\n}\n'
 (directory/'citation.bib').write_text(bib)
 metadata=''.join('<meta name="'+k+'" content="'+e(v,quote=True)+'">' for k,v in [('description',p['summary']),('citation_title',p['title']),* [('citation_author',a) for a in p['authors']],('citation_publication_date',p['date']),('citation_doi',p['doi']),('citation_journal_title',p['journal']),('keywords',p['keywords'])])
 schema={'@context':'https://schema.org','@type':'ScholarlyArticle','headline':p['title'],'author':[{'@type':'Person','name':a,**({'sameAs':'https://orcid.org/0000-0001-7200-9192'} if a=='Lijing Liu' else {})} for a in p['authors']],'identifier':p['doi'],'sameAs':doi,'url':base+path,'description':p['summary'],'isPartOf':{'@type':'Periodical','name':p['journal']}}
 if len(p['date'])==10:schema['datePublished']=p['date']
 body='<nav><a href="/">← All papers</a></nav><p class="eyebrow">'+e(p['status'])+'</p><h1>'+e(p['title'])+'</h1><p>'+e(' · '.join(p['authors']))+'</p><p class="meta">'+e(p['journal']+' · '+p['date'])+'</p><div class="links"><a href="'+doi+'">Original paper / full text</a><a href="citation.bib">Download BibTeX</a></div><h2>Research overview</h2><p>'+e(p['summary'])+'</p>'
 body+='<h2>Original abstract</h2><p>'+e(abstracts[p['slug']])+'</p><p class="meta">Abstract reproduced without changes from <a href="'+doi+'">the original publication</a> by '+e('; '.join(p['authors']))+' (2026), under <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>.</p><p><a href="'+fulltext[p['slug']]+'">Read the publicly available full text'+(' (PDF, early publication)' if p['slug']=='iberian-electricity' else ' (HTML)')+'</a></p>'
 schema['abstract']=abstracts[p['slug']]
 schema['license']='https://creativecommons.org/licenses/by/4.0/'
 if (directory/'paper.pdf').exists():
  body+='<p><a href="paper.pdf">Download full-text PDF (open access copy)</a></p><p class="meta">Unmodified publisher PDF. '+('Article in Press / early publication; not the final version of record.' if p['slug']=='iberian-electricity' else 'Published journal article.')+' Reproduced under CC BY 4.0; cite the original DOI.</p>'
  metadata+='<meta name="citation_pdf_url" content="'+base+path+'paper.pdf">'
 elif p['slug']=='iberian-electricity':metadata+='<meta name="citation_pdf_url" content="'+fulltext[p['slug']]+'">'
 if p['findings']: body+='<h2>Key findings</h2><ul>'+''.join('<li>'+e(f)+'</li>' for f in p['findings'])+'</ul>'
 if p['limits']:body+='<h2>Scope and limitations</h2><p>'+e(p['limits'])+'</p>'
 body+='<h2>Cite this work</h2><p>'+e('; '.join(p['authors'])+'. (2026). '+p['title']+'. '+p['journal']+'. ')+'<a href="'+doi+'">'+e(p['doi'])+'</a></p><pre>'+e(bib)+'</pre>'
 (directory/'index.html').write_text(page(p['title'],body,path,metadata,schema))
 cards+='<article class="card"><p class="eyebrow">'+e(p['status'])+'</p><h2><a href="'+path+'">'+e(p['title'])+'</a></h2><p>'+e(p['summary'])+'</p><p class="meta">'+e(p['journal'])+' · 2026</p></article>'
(root/'index.html').write_text(page('Lijing Liu | Research publications','<p class="eyebrow">Research publications</p><h1>Lijing Liu</h1><p>GOVCOPP &amp; DEGEIT · University of Aveiro</p><p>Research on energy markets, solar photovoltaic industry competitiveness and academic inequality.</p><p><a href="https://orcid.org/0000-0001-7200-9192">ORCID: 0000-0001-7200-9192</a></p>'+cards,'/','<meta name="description" content="Selected first-author research publications by Lijing Liu, University of Aveiro, with original paper links and citations.">'))
(root/'robots.txt').write_text('User-agent: *\nAllow: /\n\nSitemap: '+base+'/sitemap.xml\n')
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+base+path+'</loc></url>' for path in ['/']+['/papers/'+p['slug']+'/' for p in papers])+'</urlset>\n')
(root/'.nojekyll').touch()
(root/'README.md').write_text('# Lijing Liu — research publications\n\nStatic academic website: https://liulijing1.github.io/\n\nSelected first-author publications with readable HTML summaries, scholarly citation metadata, JSON-LD, BibTeX, sitemap and crawler access rules. All paper pages link to the original DOI. The AI publishing paper is explicitly labelled as an unreviewed preprint.\n\n## Publish\n\nUse the public repository `liulijing1.github.io`. In Settings → Pages select Deploy from a branch → main → /(root).\n\n## Update\n\nEdit build_site.py and run `python3 build_site.py`. Verify new claims and publication status against the original paper before publishing. Publisher content retains its original copyright and licence.\n')
print('Built',len(papers),'paper pages and homepage')
